// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    address admin;

    function setUp() public {
        c = new Size();
        admin = address(this);
    }

    function testFuzz_property(bytes32 role, address account) public {
        // Wide domain: any role and any non-zero account
        vm.assume(account != address(0));

        // Ensure the caller (this test contract) is admin so it can grant roles.
        // We deploy c as this contract, so DEFAULT_ADMIN_ROLE is granted to admin in initialize??
        // Since initialize is not called by default in `new C()`, we must initialize here.
        // However, we cannot re-deploy c in the fuzz test. So we set up initialization in setUp().

        // Grant role to account using the admin (this contract). Any address can be granted a role
        // because we hold DEFAULT_ADMIN_ROLE (checked in `_grantRole`). But wait: the mutant inverts
        // hasRole, which also breaks the `onlyRole` modifier path. That's fine — we only care about
        // the direct hasRole getter after a successful grant.
        //
        // In the reference contract, grantRole should succeed because we are the admin (the owner
        // granted all roles at initialization).

        // We must ensure that `c` has been initialized with this test contract as owner.
        // Since setUp() calls `new C()`, initialization is done via the constructor's `_disableInitializers()`,
        // leaving the proxy pattern. Actually `C` inherits UUPSUpgradeable and Initializable; the
        // constructor disables initializers, so we cannot call `initialize` afterwards.
        // This means `c` is not initialized and has no roles set. But we can still call hasRole
        // on an uninitialized contract: it reads the zero-initialized storage, returning false (reference)
        // or true (mutant). That's a perfect difference!

        // So: hasRole(role, account) on a fresh, uninitialized C returns false in the reference
        // (no role granted) and true in the mutant (negated).
        // This is the general rule: hasRole must be false when the grant flag is unset.

        // No vm.assume needed beyond account != address(0).

        // The reference must return false (since no roles are granted on the freshly deployed contract).
        // The mutant returns true for every input.
        bool has = c.hasRole(role, account);
        assertTrue(!has, "hasRole must be false for un-granted role/account");
    }
}
